const $ = s => document.querySelector(s);
const icons = {work:'M3 5h18v14H3z M3 9h18 M8 9v10',docs:'M7 3h8l4 4v14H7z M15 3v5h4 M3 7v14',skill:'M12 3 3 8l9 5 9-5-9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',template:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',source:'M4 3h12l4 4v14H4z M16 3v5h4 M8 12h8 M8 16h5',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l3 2',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',plus:'M12 5v14 M5 12h14',scan:'M3 8V3h5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5 M7 12h10',arrow:'M5 12h14 M14 7l5 5-5 5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'};
const icon = key => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[key]||icons.work}"/></svg>`;
const nav=[['work','Triển khai','03'],['docs','Phiên & bản vẽ','02'],['skill','Thư viện Skill','06'],['template','Thư viện Template',''],['source','Nguồn PDF / ảnh',''],['history','Lịch sử & chất lượng',''],['settings','Cài đặt','']];
const tasks=[{id:'T-001',name:'Chèn cửa & ký hiệu trục',skill:'INSERT_DOOR_AXIS_DEMO',state:'PREVIEW',label:'Chờ duyệt',tone:'blue',scope:'Khung A · 6.000 × 4.200 mm',description:'Bố trí cửa D01 và hai ký hiệu trục theo template kiến trúc. Chỉ tác động trong khung A.',count:8},{id:'T-002',name:'Dựng mặt cắt cầu thang',skill:'STAIR_SECTION',state:'NEEDS_INPUT',label:'Thiếu dữ liệu',tone:'amber',scope:'Khung B · 3.600 × 4.200 mm',description:'Cần cao độ tầng đã xác nhận trước khi dựng mặt cắt cầu thang.',count:0},{id:'T-003',name:'Triển khai chi tiết vệ sinh',skill:'WC_DETAIL',state:'PENDING',label:'Chờ phụ thuộc',tone:'',scope:'Khung C · 3.000 × 4.200 mm',description:'Chờ kết quả T-001. Giữ nguyên preset và tài nguyên đã khóa phiên bản.',count:12}];
let page='work', selected=0, filter='all', documentIndex=0, connected=true, stale=false, previewPolicy='ALWAYS', inputHeight='', sourceName='', scanDone=false;
let history=[{time:'09:42',title:'Bản xem trước đã sẵn sàng',text:'T-001 · 8 đối tượng mới · Trong phạm vi khung A',tone:'blue'},{time:'09:41',title:'Đã kiểm tra Skill và Template',text:'Kiến trúc Việt v1.2 · Không thiếu tài nguyên',tone:'green'},{time:'09:40',title:'Đã nhận diện 3 khung nhiệm vụ',text:'T-003 phụ thuộc T-001 · Ghi tuần tự theo bản vẽ',tone:''}];
const documents=['MB-TANG-01.dwg','MAT-CAT-A-A.dwg'];
const badge=(label,tone='')=>`<span class="badge ${tone}">${label}</span>`;
const button=(text,action,primary=false,ico='')=>`<button class="button ${primary?'primary':''}" data-action="${action}">${ico?icon(ico):''}${text}</button>`;
const heading=(title,desc,actions='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
const escapeText=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,5500)}
function navigation(){ $('#nav').innerHTML=nav.map(([id,title,count])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}" title="${title}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${title}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`).join('');$('#crumb').textContent=nav.find(n=>n[0]===page)[1]; }
function context(){return `<div class="context"><div class="document-context"><span class="file-icon">DWG</span><div><strong>${documents[documentIndex]}</strong><small>AutoCAD · Phiên AC-01 · Model Space · ${stale?'Bản vẽ đã thay đổi':'Revision 24'}</small></div>${badge(connected?'Đã kết nối':'Mất kết nối',connected?'green':'red')}${badge('Template v1.2')}</div>${button('Đổi bản vẽ','documents',false,'docs')}</div>`}
function blueprint(){return `<div class="canvas-toolbar"><span>${documents[documentIndex]} / MODEL</span><span>WCS · mm &nbsp; | &nbsp; HÌNH MINH HỌA</span></div><div class="canvas"><svg viewBox="0 0 760 370" role="img" aria-label="Minh họa mặt bằng: khung A chèn cửa và trục, khung B cầu thang, khung C vệ sinh"><defs><pattern id="hatch" width="6" height="6" patternUnits="userSpaceOnUse"><path d="M0 6 6 0" stroke="#536079" stroke-width=".6"/></pattern></defs><g stroke="#a3b0c3" fill="none" stroke-width="1.4"><path d="M83 86H674V298H83Z M90 94H667V290H90Z"/><path d="M330 94V290 M338 94V290 M500 94V290 M508 94V290 M338 190H500 M338 198H500"/><path fill="url(#hatch)" d="M83 86h591v8H83z M83 290h591v8H83z"/><path d="M116 94v26h82V94 M110 250h140v40 M278 94v69 M278 220v70 M338 230h74v60 M508 204h159"/><path d="M350 108h133v67H350z M350 118h133 M350 128h133 M350 138h133 M350 148h133 M350 158h133 M418 108v67"/><path d="M531 117h42v26h-42z M610 117h35v40h-35z M523 238h55v35h-55z M606 238h40v35h-40z"/></g><g fill="#9bacbf" font-family="Segoe UI,Arial" font-size="10" text-anchor="middle"><text x="207" y="200">PHÒNG KHÁCH</text><text x="418" y="219">CẦU THANG</text><text x="587" y="185">WC</text></g><g stroke="#52647e" fill="none" stroke-width=".8"><path d="M83 56H674 M83 48v18 M330 48v18 M500 48v18 M674 48v18 M58 86v212 M50 86h16 M50 298h16"/></g><g fill="#90a1bb" font-family="Consolas" font-size="9" text-anchor="middle"><text x="206" y="49">6 000</text><text x="418" y="49">3 600</text><text x="587" y="49">3 000</text><text x="38" y="197" transform="rotate(-90 38 197)">4 200</text></g><g stroke="#699aff" stroke-dasharray="5 4" fill="#467dfb0c"><rect x="70" y="72" width="275" height="240" rx="2"/><rect x="346" y="72" width="161" height="240" rx="2" stroke="#d9a559"/><rect x="509" y="72" width="178" height="240" rx="2" stroke="#7d8ea6"/></g><g font-family="Consolas" font-size="9"><rect x="70" y="317" width="126" height="19" rx="3" fill="#263f66"/><text x="78" y="330" fill="#a8c7ff">A / T-001 · ${tasks[0].state==='DONE'?'DONE':'PREVIEW'}</text><text x="350" y="330" fill="#e4bd7f">B / ${tasks[1].state}</text><text x="513" y="330" fill="#a4b3c8">C / ${tasks[2].state}</text></g><g stroke="${tasks[0].state==='DONE'?'#79d2a7':'#80adff'}" fill="none" stroke-width="2"><path d="M250 290h45 M250 290v-45 M250 245a45 45 0 0 1 45 45"/><path d="M104 77V301 M306 77V301" stroke-dasharray="8 5" stroke-width=".8"/><circle cx="104" cy="77" r="11" fill="#18243a"/><circle cx="306" cy="77" r="11" fill="#18243a"/></g><g fill="#a8c7ff" font-family="Consolas" font-size="10" text-anchor="middle"><text x="104" y="81">1</text><text x="306" y="81">2</text><text x="274" y="237">D01</text></g><g stroke="#72869c" stroke-width="1"><path d="M29 339h22 M29 339v-22"/></g><g fill="#8fa6bf" font-size="8"><text x="54" y="342">X</text><text x="26" y="312">Y</text></g></svg><div class="canvas-note">${tasks[0].state==='DONE'?'KẾT QUẢ MẪU':'PREVIEW'} · Không gian minh họa, không đọc DWG thật</div></div><div class="canvas-legend"><span><i class="legend-line"></i>Chờ duyệt</span><span><i class="legend-line orange"></i>Thiếu dữ liệu</span><span><i class="legend-line grey"></i>Chờ phụ thuộc</span></div>`}
function inspector(){const t=tasks[selected];let action=t.state==='PREVIEW'?button('Xem & duyệt trong AutoCAD','review',true,'eye'):t.state==='NEEDS_INPUT'?`<label class="field-label" for="height">CAO ĐỘ TẦNG ĐÃ XÁC NHẬN (mm)</label><input class="input" id="height" inputmode="decimal" type="number" min="2000" max="6000" value="${escapeText(inputHeight)}" aria-describedby="height-help height-error" style="width:100%"><p id="height-help" class="hint">Nhập giá trị từ hồ sơ nguồn, trong khoảng 2.000–6.000 mm của preset mẫu.</p><p id="height-error" role="alert" class="hint"></p>${button('Xác nhận dữ liệu & lập kế hoạch','height',true)}`:t.state==='DONE'?`<div class="notice">✓ Áp dụng mẫu hoàn tất. QA: đạt 4/4 kiểm tra.</div>`:t.state==='READY'?button('Lập kế hoạch mẫu','plan',true):t.state==='CANCELLED'?button('Tạo lại bản xem trước','plan',true):`<div class="notice amber">Đang chờ T-001 hoàn thành. Chỉ phân tích trước; chưa ghi vào DWG.</div>`;return `<aside class="panel"><div class="panel-header"><h2>Chi tiết nhiệm vụ</h2><span class="mono">${t.id}</span></div><div class="inspector"><div class="inspector-title"><span class="eyebrow">KHUNG ${'ABC'[selected]}</span>${badge(t.label,t.tone)}</div><h2>${t.name}</h2><p class="description">${t.description}</p><label class="field-label">SKILL ĐANG SỬ DỤNG</label><div class="field-value"><strong>${t.skill}</strong>Phiên bản 1.0.0 · Đã kiểm tra phụ thuộc</div><label class="field-label">TEMPLATE DÙNG CHUNG</label><div class="field-value"><strong>Kiến trúc Việt</strong>v1.2 · Đã khóa phiên bản cho nhiệm vụ</div><div class="divider"></div><div class="meta-grid"><div><small>Phạm vi</small><strong>Khung ${'ABC'[selected]} · Model</strong></div><div><small>Đối tượng mới</small><strong>${t.count||'Chưa xác định'}</strong></div><div><small>Chế độ xem trước</small><strong>${previewPolicy}</strong></div><div><small>Phụ thuộc</small><strong>${selected===2?'T-001':'Không có'}</strong></div></div><div class="divider"></div><h3>Kiểm tra trước thực thi</h3><ul class="checklist"><li><span class="check">✓</span>Đúng phiên và bản vẽ đích</li><li><span class="check">✓</span>Phạm vi ${t.scope}</li><li><span class="check">✓</span>Skill & Template hợp lệ</li><li><span class="${stale?'':'check'}">${stale?'!':'✓'}</span>${stale?'Bản vẽ đã thay đổi: cần tạo lại preview':'Revision khớp với kế hoạch'}</li></ul>${!connected?'<div class="notice amber">Mất kết nối AutoCAD. Không thể áp dụng.</div>':''}${stale?button('Tạo lại preview trên bản vẽ đích','plan'):''}${action}<p class="hint">Duyệt/hủy cục bộ không gọi AI lại.</p></div></aside>`}
function work(){return heading('Không gian triển khai','Từ yêu cầu đến bản vẽ, trong đúng phạm vi của bạn.',button('Quét khung nhiệm vụ','scan',false,'scan'))+context()+`<div class="stats"><div class="stat"><small>Nhiệm vụ trong bản vẽ</small><strong>03<span>3 khung được nhận diện</span></strong></div><div class="stat"><small>Đang chờ duyệt</small><strong>${tasks.filter(t=>t.state==='PREVIEW').length.toString().padStart(2,'0')}<span>Kiểm tra trước khi áp dụng</span></strong></div><div class="stat"><small>Cần bổ sung dữ liệu</small><strong>${tasks.filter(t=>t.state==='NEEDS_INPUT').length.toString().padStart(2,'0')}<span>Thông số từ hồ sơ nguồn</span></strong></div></div><div class="workspace"><div><section class="panel"><div class="panel-header"><h2>Bản vẽ & phạm vi nhiệm vụ</h2>${badge('Chế độ xem trước · '+previewPolicy,'blue')}</div>${blueprint()}</section><section class="panel task-list"><div class="panel-header"><h2>Danh sách nhiệm vụ</h2><small>Ghi tuần tự trên cùng DWG</small></div><div class="filters">${[['all','Tất cả'],['PREVIEW','Chờ duyệt'],['NEEDS_INPUT','Thiếu dữ liệu']].map(([value,label])=>`<button class="filter ${filter===value?'active':''}" aria-pressed="${filter===value}" data-filter="${value}">${label}</button>`).join('')}</div>${tasks.map((t,i)=>filter==='all'||t.state===filter?`<div class="task-row ${i===selected?'selected':''}" role="button" tabindex="0" aria-label="${t.id}: ${t.name}, ${t.label}" aria-pressed="${i===selected}" data-task="${i}"><span class="task-symbol">${'ABC'[i]}</span><div><strong>${t.name}</strong><small>${t.id} · ${t.skill}</small></div>${badge(t.label,t.tone)}</div>`:'').join('')||'<p class="empty">Không có nhiệm vụ ở trạng thái này.</p>'}</section></div>${inspector()}</div>`}
function docs(){return heading('Phiên & bản vẽ','Chọn rõ phiên AutoCAD và DWG đích trước khi triển khai.',button('Làm mới danh sách','refresh',false,'scan'))+`<div class="content-stack">${[0,1].map(i=>`<section class="panel session-card"><div class="session-head"><div><span class="eyebrow">PHIÊN AC-0${i+1}</span><h2>AutoCAD · Máy trạm thiết kế</h2><small>Plugin mẫu 0.1 · ${i===0?'2 bản vẽ đang mở':'Chưa mở bản vẽ'}</small></div>${badge(i===0?(connected?'Đã kết nối':'Mất kết nối'):'Đã kết nối',i===0&&!connected?'red':'green')}</div>${i===0?documents.map((d,k)=>`<div class="document-row"><div><strong>${d}</strong><small>Dự án / Kiến trúc / ${d} · Model · ${k===0?'Có thay đổi chưa lưu':'Đã lưu'}</small></div><div class="actions">${k===documentIndex?badge('Bản vẽ đích','blue'):button('Chọn làm đích','doc-'+k)}${button('Lưu mẫu','save-'+k)}</div></div>`).join(''):'<p class="description">Mở một DWG trong AutoCAD để bắt đầu. Phiên này chưa có tài liệu đích.</p>'}</section>`).join('')}</div>`}
const skillCards=[['Cửa & ký hiệu trục','INSERT_DOOR_AXIS_DEMO','Chèn block cửa và tên trục trong phạm vi khung.','Sẵn sàng'],['Mặt cắt cầu thang','STAIR_SECTION','Dựng từ mặt bằng và cao độ đã xác nhận.','Sẵn sàng'],['Chi tiết vệ sinh','WC_DETAIL','Cấu tạo và ghi chú theo preset tiêu chuẩn.','Sẵn sàng'],['Mặt cắt kiến trúc','BUILDING_SECTION','Đối chiếu mặt bằng, mặt đứng và cao độ nguồn.','Sẵn sàng'],['Lát gạch','FLOOR_TILING','Bố trí mạch gạch từ đường bao phòng.','Thiếu tool'],['Ảnh / PDF → mặt bằng','FLOORPLAN_FROM_SOURCE','Hiệu chuẩn và dựng đối tượng CAD có cấu trúc.','Đang tắt']];
let disabledSkills=new Set([5]);
function skills(){return heading('Thư viện Skill','Quy trình nghiệp vụ độc lập, sử dụng chung bộ CAD Tools.',button('Nhập gói Skill','import-skill',false,'plus'))+`<div class="searchbar"><input class="input" id="skill-search" aria-label="Tìm Skill" placeholder="Tìm theo tên hoặc mã Skill…"><span class="badge">6 Skill · Dữ liệu minh họa</span></div><div class="card-grid" id="skill-cards">${skillCards.map((s,i)=>`<article class="library-card" data-search="${s.join(' ').toLowerCase()}"><div class="card-art">${icon(i===0?'docs':'skill')}</div>${badge(disabledSkills.has(i)?'Đang tắt':s[4]||s[3],i===4?'amber':disabledSkills.has(i)?'':'green')}<h2>${s[0]}</h2><div class="mono">${s[1]}</div><p>${s[2]}</p><div class="card-foot"><small>v1.0.0 · ${i===4?'Thiếu create_hatch':'Phụ thuộc đã kiểm tra'}</small>${button(disabledSkills.has(i)?'Bật Skill':'Tắt Skill','skill-'+i)}</div></article>`).join('')}</div><input hidden id="skill-file" type="file" accept=".json,.zip">`}
function templates(){return heading('Thư viện Template','Một nguồn tiêu chuẩn chung cho toàn bộ Skill và nhiệm vụ.',button('Nhập tài nguyên','import-template',false,'plus'))+`<div class="notice" style="margin-bottom:20px">Thư viện gốc chỉ đọc khi chạy nhiệm vụ. Bản cập nhật được kiểm tra trước khi công bố; nhiệm vụ đang chạy giữ phiên bản đã khóa.</div><div class="card-grid">${[['Block cửa D01','BLOCK · DWG','Cửa đơn 900 mm, thuộc tính và hướng mở.'],['Ký hiệu trục','BLOCK · DWG','Tên trục, số hiệu và quy tắc bố trí.'],['Kiến trúc Việt','PROFILE · v1.2','Layer, text/dim style, hatch và preset kiến trúc.']].map((x,i)=>`<article class="library-card"><div class="card-art">${i===0?'<svg viewBox="0 0 120 100" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 80h75 M20 80V15 M20 15a65 65 0 0 1 65 65"/><path d="M15 85h85" stroke-dasharray="4 4"/></svg>':i===1?'<svg viewBox="0 0 120 100" fill="none" stroke="currentColor"><path d="M60 33v57" stroke-dasharray="6 4"/><circle cx="60" cy="25" r="17"/><text x="60" y="31" fill="currentColor" stroke="none" text-anchor="middle" font-size="18">A</text></svg>':icon('template')}</div><span class="eyebrow">${x[1]}</span><h2>${x[0]}</h2><p>${x[2]}</p><div class="card-foot">${badge('Đã công bố','green')}${button('Xem chi tiết','asset-'+i)}</div></article>`).join('')}</div><input hidden id="template-file" type="file" accept=".dwg,.dwt,.json,.zip">`}
function sources(){return heading('Nguồn PDF / ảnh','Hiệu chuẩn bằng mốc tin cậy trước khi dựng bản vẽ.')+`<div class="wide-layout"><section class="panel padded"><label class="upload" style="display:block" for="source-file"><span class="eyebrow">PDF VECTOR · PDF SCAN · JPG · PNG</span><h2>Thêm tài liệu nguồn</h2><p>Chọn tệp từ máy tính để thử luồng tiếp nhận.</p><input id="source-file" type="file" accept=".pdf,.png,.jpg,.jpeg"></label><div class="divider"></div><h2 style="font-size:16px">${sourceName?escapeText(sourceName):'Chưa có tài liệu nguồn'}</h2><p class="description" style="margin-top:8px">${sourceName?'Đã chọn tệp. Bản mẫu chưa trích xuất vector hoặc chạy OCR.':'Chọn tài liệu để xác định trang, vùng và hai điểm chuẩn.'}</p><label class="field-label" for="calibration">KHOẢNG CÁCH CHUẨN (mm)</label><input class="input" id="calibration" type="number" min="1" placeholder="Ví dụ: 6.000" aria-describedby="calibration-help"><p id="calibration-help" class="hint">Bản thật yêu cầu chọn hai điểm tương ứng trên ảnh và kiểm chứng kích thước.</p></section><aside class="panel padded"><h2 style="font-size:16px">Các bước xử lý</h2><ol class="description" style="padding-left:18px;line-height:2.5"><li>Chọn trang và vùng nguồn</li><li>Hiệu chuẩn tỷ lệ</li><li>Trích vector / OCR</li><li>Xác nhận phần chưa chắc chắn</li><li>Ánh xạ template & tạo preview</li></ol><div class="notice amber">Thiếu kích thước hoặc độ tin cậy thấp: cần bổ sung dữ liệu trước khi tạo hình học chính thức.</div></aside></div>`}
function histories(){return heading('Lịch sử & chất lượng','Theo dõi kế hoạch, thay đổi và kết quả kiểm tra theo từng DWG.')+context()+`<section class="panel"><div class="panel-header"><h2>Hoạt động trong bản vẽ</h2>${badge('Nhật ký mẫu')}</div><div class="timeline">${history.map(e=>`<article class="event"><span class="event-time">${e.time}</span><div><h3>${e.title}</h3><p>${e.text}</p></div></article>`).join('')}</div></section><div class="notice" style="margin-top:18px">Khôi phục trong bản thật phải dựa trên checkpoint, revision và nhật ký thực thi đã xác minh. Bản mẫu này chỉ thể hiện luồng giao diện.</div>`}
function settings(){return heading('Cài đặt không gian','Chính sách xem trước và tình huống kiểm tra bản mẫu.')+`<section class="panel padded"><div class="setting-row"><div><h3>Chế độ xem trước</h3><p>Giai đoạn thử nghiệm dùng ALWAYS. SMART là định hướng vận hành.</p></div><select id="policy" aria-label="Chế độ xem trước">${['ALWAYS','SMART','OFF'].map(v=>`<option ${previewPolicy===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="setting-row"><div><h3>Kết nối AutoCAD mẫu</h3><p>Tắt để kiểm tra trạng thái mất kết nối và chặn áp dụng.</p></div><label><input class="toggle" id="connected" type="checkbox" ${connected?'checked':''}> Đã kết nối</label></div><div class="setting-row"><div><h3>Mô phỏng bản vẽ thay đổi</h3><p>Preview cũ hết hiệu lực khi revision thay đổi.</p></div><label><input class="toggle" id="stale" type="checkbox" ${stale?'checked':''}> Revision mới</label></div><div class="setting-row"><div><h3>Dữ liệu bản mẫu</h3><p>Khôi phục trạng thái ban đầu để thử lại luồng.</p></div>${button('Đặt lại mô phỏng','reset')}</div><p class="hint">Các lựa chọn trên chỉ tác động đến giao diện mẫu trong phiên hiện tại.</p></section>`}
function render(focus=false){navigation();$('#main').innerHTML=({work,docs,skill:skills,template:templates,source:sources,history:histories,settings})[page]();if(focus)$('#main').focus()}
function route(value){page=value;filter='all';render(true)}
function review(){const t=tasks[selected];if(t.state!=='PREVIEW')return;$('#review-content').innerHTML=`<div class="notice ${stale||!connected?'amber':''}">${!connected?'Mất kết nối: kết nối lại AutoCAD trước khi tiếp tục.':stale?'Bản vẽ đã thay đổi. Cần tạo lại preview trước khi duyệt.':'Kế hoạch đã kiểm tra. Duyệt sẽ áp dụng đúng bản xem trước này.'}</div><div class="divider"></div>${[['Bản vẽ đích',documents[documentIndex]],['Phiên / Không gian','AC-01 / Model'],['Nhiệm vụ / Phạm vi',t.id+' / Khung '+'ABC'[selected]],['Thay đổi',t.count+' tạo mới · 0 sửa · 0 xóa'],['Skill / Template','1.0.0 / Kiến trúc Việt 1.2'],['Revision / Plan','24 / PLAN-'+t.id+'-01']].map(([k,v])=>`<div class="review-item"><span>${k}</span><strong>${v}</strong></div>`).join('')}<div class="divider"></div><p class="description">Bản mẫu mô phỏng thao tác duyệt tại palette AutoCAD. Không ghi vào DWG thật; không gọi model.</p>`;$('#apply-plan').disabled=stale||!connected;$('#review').showModal()}
document.addEventListener('click',e=>{const n=e.target.closest('[data-page]');if(n){route(n.dataset.page);return}const row=e.target.closest('[data-task]');if(row){selected=Number(row.dataset.task);render();return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='documents')route('docs');else if(a.startsWith('doc-')){documentIndex=Number(a.slice(4));tasks.forEach(t=>{if(t.state==='PREVIEW'||t.state==='DONE')Object.assign(t,{state:'READY',label:'Cần lập lại kế hoạch',tone:'amber'})});stale=true;notify('Đã đổi bản vẽ đích. Cần tạo lại kế hoạch; preview trước thuộc DWG cũ.');route('work')}else if(a==='review')review();else if(a==='scan'){scanDone=true;notify('Đã quét mẫu: 3 khung, 1 quan hệ phụ thuộc. Không tạo nhiệm vụ trùng.')}else if(a==='refresh')notify('Đã làm mới danh sách phiên mẫu.');else if(a.startsWith('save-'))notify('Mô phỏng lưu '+documents[Number(a.slice(5))]+'. Không ghi tệp thật.');else if(a==='height'){let h=Number($('#height').value);inputHeight=$('#height').value;if(!h||h<2000||h>6000){$('#height-error').textContent='Nhập cao độ từ 2.000 đến 6.000 mm cho preset này.';$('#height').setAttribute('aria-invalid','true');$('#height').focus();return}Object.assign(tasks[selected],{state:'PREVIEW',label:'Chờ duyệt',tone:'blue',count:24,description:'Đã xác nhận cao độ '+h.toLocaleString('vi-VN')+' mm. Có thể kiểm tra và duyệt kế hoạch mẫu.'});render();notify('Đã tạo preview mẫu từ cao độ đã xác nhận.')}else if(a==='plan'){Object.assign(tasks[selected],{state:'PREVIEW',label:'Chờ duyệt',tone:'blue'});tasks.forEach((t,i)=>{if(i!==selected&&t.state==='PREVIEW')Object.assign(t,{state:'READY',label:'Cần lập lại kế hoạch',tone:'amber'})});stale=false;render();notify('Đã tạo lại preview mẫu trên bản vẽ đích hiện tại.')}else if(a.startsWith('skill-')){let i=Number(a.slice(6));if(i===4){notify('Không thể bật: thiếu tool create_hatch. Bổ sung tool và kiểm tra dependency trước.');return}disabledSkills.has(i)?disabledSkills.delete(i):disabledSkills.add(i);render();notify('Đã cập nhật trạng thái Skill mẫu. Task đã chốt giữ snapshot riêng.')}else if(a==='import-skill')$('#skill-file').click();else if(a==='import-template')$('#template-file').click();else if(a.startsWith('asset-'))notify('Tài nguyên mẫu v1.2 · Đã khóa checksum · Dùng bởi '+(Number(a.slice(6))+1)+' Skill.');else if(a==='reset')location.reload()});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-task]')){e.preventDefault();e.target.click()}});
document.addEventListener('input',e=>{if(e.target.id==='skill-search'){const term=e.target.value.toLowerCase();document.querySelectorAll('[data-search]').forEach(c=>c.hidden=!c.dataset.search.includes(term))}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='policy'){previewPolicy=e.target.value;notify('Đã đổi chính sách mẫu thành '+previewPolicy+'.');}if(id==='connected')connected=e.target.checked;if(id==='stale')stale=e.target.checked;if(id==='source-file'){sourceName=e.target.files[0]?.name||'';render();notify('Đã chọn tài liệu. OCR và hiệu chuẩn chưa được kết nối.')}if(id==='skill-file'||id==='template-file')notify('Đã chọn gói '+(e.target.files[0]?.name||'')+'. Bản thật sẽ kiểm tra schema, checksum và phụ thuộc trước khi nhập.');});
$('#apply-plan').onclick=()=>{if(stale||!connected||tasks[selected].state!=='PREVIEW')return;const t=tasks[selected];Object.assign(t,{state:'DONE',label:'Hoàn tất',tone:'green'});if(selected===0)Object.assign(tasks[2],{state:'READY',label:'Sẵn sàng',tone:'green'});history.unshift({time:'Bây giờ',title:t.id+' · Áp dụng mẫu thành công',text:t.count+' đối tượng mới · QA 4/4 · Receipt mẫu đã ghi nhận',tone:'green'});$('#review').close();render();notify('Áp dụng mẫu hoàn tất. Thao tác lặp lại đã được chặn bằng trạng thái nhiệm vụ.');};
$('#cancel-plan').onclick=()=>{Object.assign(tasks[selected],{state:'CANCELLED',label:'Đã hủy',tone:''});$('#review').close();render();notify('Đã hủy preview mẫu. Không thay đổi bản vẽ.');};
$('#close-dialog').onclick=()=>$('#review').close();
$('#review').addEventListener('close',()=>document.querySelector('[data-action="review"]')?.focus());
$('#theme-toggle').onclick=()=>{document.body.classList.toggle('theme-dark');notify('Đã đổi giao diện cho bản mẫu.');};
$('#help').onclick=()=>notify('Thử chọn task, duyệt/hủy preview, bổ sung cao độ hoặc kiểm tra mất kết nối trong Cài đặt.');
render();
